"""Generate the owned synthetic Hana and IBK card exports inside a test temp folder."""
from __future__ import annotations

import argparse
import base64
from pathlib import Path

_FIXTURES = {
    "hana": ("hana-card-synthetic.csv", ""),
    "ibk": ("ibk-card-synthetic.xlsx", ""),
}


def fixture_name(provider: str) -> str:
    return _FIXTURES[provider][0]


def fixture_bytes(provider: str) -> bytes:
    return base64.b64decode(_FIXTURES[provider][1], validate=True)


def write_fixtures(out_dir: Path) -> dict[str, Path]:
    out_dir.mkdir(parents=True, exist_ok=True)
    written = {}
    for provider, (name, _encoded) in _FIXTURES.items():
        destination = out_dir / name
        destination.write_bytes(fixture_bytes(provider))
        written[provider] = destination
    return written


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--out-dir", type=Path, required=True)
    write_fixtures(parser.parse_args().out_dir)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())